                //Fill rozpis - metoda fillrozpis z fupty
                fillRozpis() {
                    if (this._param.sml_dok_fillrcr == 1 /* Interface.RizeniPredplneniRozpisuNaRoky.ng_fillrcrYes */ && this.model.findoc?.num_rok == 1 &&
                        this.model.findoc.typ_ceny == 10 /* Interface.TypCeny.ng_typcenyPevna */ && (this.model.findoc.c_mena != this.model?.findoc?.smlrok?.c_mena ||
                        this.model.findoc.mena != this.model?.findoc?.smlrok?.mena)) {
                        //!tak teď je možné provést předplnění
                        //358.20 21.03.08 volána kontrla v rámci dialogu
                        if ($.content(this.tabs?.tabFinancovani).loaded == true) {
                            //vynucená evidence dokladu - nastavení částky  -  pouze pro stavy od evidence
                            if ((this.model.sml_stav ?? 0) > 10 /* Interface.StavDokladu.ng_stavNavrh */) {
                                this.beginOperation();
                                this.isl.DetailDokladu.evidence({ data: this.model }).getData().always(() => { this.endOperation(); });
                            }
                            if (this.tabs?.tabFinancovani)
                                this.tabs?.tabFinancovani.gfield("refresh");
                        }
                    }
                }
                //Nstaví ac_ver_zak z hlavního modelu dokladu
                setOldAcVerZak() {
                    this.findFields("ac_ver_zak" /* Interface.GSml_FinDtoNames.ac_ver_zak */).gfield("setValue", { ac_ver_zak: this.model.findoc?.ac_ver_zak }, false);
                }
                //VALIDOVÁNÍ AC SML, validace proběhne na serveru. Momentálně validace probíhá ale pomocí tlačítka na detailu, čistě pro testovací účely
                //NAstavení příznaku
                validateAcSml() {
                    var validator = new Gordic.Validators.Base({ message: "" });
                    validator.validate = (value, source) => {
                        this.model.SmlValidators.ac_sml = true;
                        return true;
                    };
                    validator.stopping = false;
                    return validator;
                }
                //Get Stav Smluv
                GetSmlStav(mp_stav) {
                    if (mp_stav == 10 /* Interface.StavDokladu.ng_stavNavrh */)
                        return "Návrh";
                    else if (mp_stav == 20 /* Interface.StavDokladu.ng_stavEvidence */)
                        return "Evidence";
                    else if (mp_stav == 23 /* Interface.StavPolozky.ng_upsEvidenceValidate */)
                        return "Evidence, schválený FP";
                    else if (mp_stav == 30 /* Interface.StavDokladu.ng_stavValidate */)
                        return "Schváleno";
                    else if (mp_stav == 50 /* Interface.StavDokladu.ng_stavClose */)
                        return "Ukončeno";
                    else if (mp_stav == 90 /* Interface.StavDokladu.ng_stavStorno */)
                        return "Storno";
                    else
                        return "";
                }
                //Set Stav Smluv
                SetSmlStav(sml_stav_p, num_pol_p, num_pol_sch_p) {
                    //!360.23 30.07.09 dynamické = vytvoření nového stavu
                    let l_stav = sml_stav_p;
                    if (sml_stav_p == 20 /* Interface.StavPolozky.ng_upsEvidence */ && num_pol_p > 0 && num_pol_p == num_pol_sch_p)
                        l_stav = 23 /* Interface.StavPolozky.ng_upsEvidenceValidate */;
                    return l_stav;
                }
